78	        String countryCode = digits.substring(0, countryCodeLength);
79	        String national = digits.substring(countryCodeLength);
80	        StringBuilder grouped = new StringBuilder();
81	        for (int i = 0; i < national.length(); i++) {
82	            if (i > 0 && i % 3 == 0) {
83	                grouped.append(' ');
84	            }
85	            grouped.append(national.charAt(i));
